import React from "react";
import "../Style/HouseDetailsModal.css";

export default function FormSelectionModal({ isOpen, onClose, onSelect }) {
  if (!isOpen) return null;

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <div className="modal-header">
          <h3>Select Form Type</h3>
          <button onClick={onClose} className="modal-close-button">X</button>
        </div>

        <div className="modal-body" style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
          <button onClick={() => onSelect("ptax")} className="button-primary">Form 1 - PTAX</button>
          <button onClick={() => onSelect("form2")} className="button-primary">Form 2</button>
          <button onClick={() => onSelect("form3")} className="button-primary">Form 3</button>
          <button onClick={() => onSelect("form4")} className="button-primary">Form 4</button>
          <button onClick={() => onSelect("form5")} className="button-primary">Form 5</button>
        </div>
      </div>
    </div>
  );
}
